import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"5、【需】 乾下坎上","description":"周易尚氏学 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"周易尚氏学 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/010.md","filePath":"zh/classics/shangshi/010.md"}'),s={name:"zh/classics/shangshi/010.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>乾为行。行而遇险。故曰需。需待也。归藏作溽。坎兑皆水。故溽。溽湿也。而溽与濡音义并同。杨氏古音云。溽人余切。归藏易。需卦作溽。同濡。案孟子。是何濡滞也。是溽有迟义。古文多省笔。疑需为古文濡字。与归藏同。且濡滞亦有须义。与彖传不背。周易本因二易而作。溽濡需不过字形之辗转耳。音义并同也。卦辞皆指九五。五上下皆阴。故有孚。互离故光。得位放亨。贞吉者。卜问则吉也。坤为水。为大川。易林贲之损云。龙蛇所聚。大水来处。以损互震为龙蛇。互坤为水。又师之复。渊泉堤防。水道利通。亦以复坤为泉为水。此外九家。说蛊之利涉大川云。此卦乾天有河。坤地有水。二爻升降。出入乾坤。利涉大大川也。亦以坤为大川。利涉谓五。言五居坤中。孚于上下而利也。故彖传以位乎天位。往有功释之。而虞翻谓往指二。二失位。变阴涉坎。故利涉。夫以坎为大川。涉之而利。则不必需矣。是背卦义也。彼夫蹇无坤也。而曰利西南。以蹇五居坤中也。需五亦居坤中。坤为大川。当位而尊。上下皆孚。故曰往有功。五居外。故曰往。非必内卦往外卦。方谓往也。此卦只五爻能利涉。他爻无利者。自坤水象失传。不知五所涉者为坤水。为大川。必以坎为大川。于是易之利涉大川。无一得解者。</p><p>彖曰。需。须也。险在前也。刚健而不陷。其义不困穷矣。需有孚光亨贞吉。位乎天位。以正中也。利涉大川。往有功也。</p><p>须待也。待则不陷于险中。故不困穷。释需之故也。位乎天位。往有功。皆谓九五。谓九五居坤水之中。上下皆孚。有功即利涉。虞翻以二当之。失彖传旨矣。</p><p>象曰。云上于天。需。君子以饮食宴乐。</p><p>坎为云。故曰云上于天。二四兑。兑口。故曰饮食。兑悦。故曰宴乐。乾为君子。言君子饮食宴乐。从容以俟也。</p><p>初九。需于郊。利用恒。无咎。</p><p>乾为郊。初临重阳。阳遇阳得敌。不能行。故利用恒。恒久也常也。言潜龙勿用。守常不变也。守常不动。故无咎。阳遇阳行难。需而不进。故象曰不犯难行。大畜初九曰。有厉利己。厉与难皆指二三。此与鼎九二慎所之。大有初九曰无交。大壮初九曰征凶。夬初九曰往不胜。姤九三曰其行次且。皆因阳遇阳。乃二千年说者。皆以需坎为难。谓初不取四。为不犯难。岂知难为二三。二三皆阳。阳遇阳行难。故不取四而用恒。非以坎为难而不取也。故夫同性相敌。异性相感之理不明。则易本立失。此不犯难及有厉利己等辞。所以永不得解也。</p><h3 id="象曰。需于郊。不犯难行也。利用恒无咎。未失常也。" tabindex="-1">象曰。需于郊。不犯难行也。利用恒无咎。未失常也。 <a class="header-anchor" href="#象曰。需于郊。不犯难行也。利用恒无咎。未失常也。" aria-label="Permalink to “象曰。需于郊。不犯难行也。利用恒无咎。未失常也。”">​</a></h3><p>阳遇阳得敌需而不进。故曰不犯难行。难指二三。</p><p>九二。需于沙。小有言。终吉。</p><p>沙近水。二较初略进。故曰需于沙。二至四伏艮。艮为沙。有言者争讼也。乾为言。见左传。兑口亦为言。见易林。乃兑言向外。与乾言相背。故争讼。夬四之闻言不信。即如此取象也。兑为小故小有言。有言不吉。然而吉者。象曰衍在中。以居沙衍之中也。穆天子传。天子遂东征。南绝沙衍。盖水中有沙曰衍。故曰衍在中。以象中位也。象曰。虽小有言。以吉终者。明有言本不吉。然而吉者。以得中位也。虞翻用半象。谓三四震象半见。为小有言。穿凿之说也。凡易云有言。及闻言不信。有言不信者。皆争讼也。非言之有无也。左传昭五年。以谦为馋。首发其义。焦氏易林。畅述其旨。于是二千年有言误解。尽行暴露。与利涉大川同。说详焦氏易诂中。</p><h3 id="象曰。需于沙。衍在中也。虽小有言。以吉终也。" tabindex="-1">象曰。需于沙。衍在中也。虽小有言。以吉终也。 <a class="header-anchor" href="#象曰。需于沙。衍在中也。虽小有言。以吉终也。" aria-label="Permalink to “象曰。需于沙。衍在中也。虽小有言。以吉终也。”">​</a></h3><p>解见前。</p><p>九三。需于泥。致寇至。</p><p>震九四云。震队泥。以坎为泥也。九三去险益近。故曰需于泥。坎为寇。三近坎。故曰致寇至。</p><h3 id="象曰。需于泥。灾在外也。自我致寇。敬慎不败也。" tabindex="-1">象曰。需于泥。灾在外也。自我致寇。敬慎不败也。 <a class="header-anchor" href="#象曰。需于泥。灾在外也。自我致寇。敬慎不败也。" aria-label="Permalink to “象曰。需于泥。灾在外也。自我致寇。敬慎不败也。”">​</a></h3><p>坎为灾。灾在外。明尚未罹灾。致寇至。明寇尚未至也。致之故在我。我能敬慎。则不至矣。不至则不败。乾为惕。故曰敬慎。</p><p>六四。需于血。出自穴。</p><p>血。洫之省字。古文如此者。不可胜数。且沟洫亦坎象也。诸家以坎有血象。便作需于血。不辞甚矣。兑为穴。易林乾之咸云。反得丹穴。豫之兑云。秋蛇向穴。皆以兑为穴。言四之所处。前临沟洫。故曰需于洫。而居兑穴之上。故曰出自穴。毛奇龄惠栋焦循等。皆以坎为穴。用象既误。故于出义不合也。(祇姚配中诂出字得解。)</p><h3 id="象曰。需于血。顺以听也。" tabindex="-1">象曰。需于血。顺以听也。 <a class="header-anchor" href="#象曰。需于血。顺以听也。" aria-label="Permalink to “象曰。需于血。顺以听也。”">​</a></h3><p>四阴宜顺五阳。坎为耳。故曰听。听从也。</p><p>九五。需于酒食。贞吉。</p><p>坎为酒。食。实也。颐自求口实。郑作食。是食实可通用。坎中实。故坎为食。易林履之蹇云。天下饶食。谦之坎。食非其任。皆以坎为食。酒食在上。兑口承之。故曰需于酒食。贞吉者。卜问吉也。</p><h3 id="象曰。需于酒食。以中正也。" tabindex="-1">象曰。需于酒食。以中正也。 <a class="header-anchor" href="#象曰。需于酒食。以中正也。" aria-label="Permalink to “象曰。需于酒食。以中正也。”">​</a></h3><p>五位中正。释贞吉之故也。</p><p>上六。入于穴。有不速之客。三人来。敬之。终吉。</p><p>互兑为穴。上来应三。则入于兑穴矣。而阳必上升。故曰不速之客。马云。速召也。乾为人。上应在三。故曰三人来。坎为畏惧。故曰敬之。言阴宜顺阳也。上居卦终。故曰终吉。</p><h3 id="象曰。不速之客来。敬之终吉。虽不当位。未大失也。" tabindex="-1">象曰。不速之客来。敬之终吉。虽不当位。未大失也。 <a class="header-anchor" href="#象曰。不速之客来。敬之终吉。虽不当位。未大失也。" aria-label="Permalink to “象曰。不速之客来。敬之终吉。虽不当位。未大失也。”">​</a></h3><p>象明曰不速之客来。来而不当位。言三升上。不当位也。非谓上六本不当位。王弼不明升降之理。便谓初上无位。真妄说也。苟爽云。上退居三。虽不当位。承阳有实。故未大失。固的解也。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
